    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Fill rectangular, uniformly colored outlines around a blank interior.
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == bg:
                        continue
                    border = (
                        [grid[r0][c] for c in range(c0, c1 + 1)] +
                        [grid[r1][c] for c in range(c0, c1 + 1)] +
                        [grid[r][c0] for r in range(r0 + 1, r1)] +
                        [grid[r][c1] for r in range(r0 + 1, r1)]
                    )
                    if any(v != color for v in border):
                        continue
                    if not all(grid[r][c] == bg
                               for r in range(r0 + 1, r1)
                               for c in range(c0 + 1, c1)):
                        continue

                    ih, iw = r1 - r0 - 1, c1 - c0 - 1
                    fill = 7 if ih == iw and ih % 2 == 1 else 2
                    for r in range(r0 + 1, r1):
                        for c in range(c0 + 1, c1):
                            out[r][c] = fill
    return out
